"""
Minimal refutation of the Euler-equals-semantics conjecture.

The conjecture asserts, for every finite argumentation framework (A, R):

    chi(K(AF)) = #(preferred extensions) - |grounded extension|.

We exhibit the smallest possible counterexample: a single argument that attacks
nothing (R0 on one vertex). There K(AF) is a single point (chi = 1), there is
exactly one preferred extension, and the grounded extension has size one, so the
right-hand side is 1 - 1 = 0 != 1.
"""
from __future__ import annotations
from itertools import combinations, chain
from typing import FrozenSet, List, Set, Tuple

Ext = FrozenSet[int]
Rel = Set[Tuple[int, int]]


def powerset(xs: List[int]) -> List[Ext]:
    return [frozenset(c) for c in chain.from_iterable(
        combinations(xs, k) for k in range(len(xs) + 1))]


def conflict_free(s: Ext, r: Rel) -> bool:
    return not any((a, b) in r for a in s for b in s)


def defends(s: Ext, a: int, r: Rel) -> bool:
    return all(any((c, b) in r for c in s) for (b, t) in r if t == a)


def admissible(s: Ext, r: Rel) -> bool:
    return conflict_free(s, r) and all(defends(s, a, r) for a in s)


def euler(args: List[int], r: Rel) -> int:
    return sum((-1) ** (len(s) - 1) for s in powerset(args)
               if conflict_free(s, r) and len(s) > 0)


def preferred(args: List[int], r: Rel) -> List[Ext]:
    adm = [s for s in powerset(args) if admissible(s, r)]
    return [s for s in adm if not any(s < t for t in adm)]


def grounded(args: List[int], r: Rel) -> Ext:
    cur: Ext = frozenset()
    while True:
        nxt = frozenset(a for a in args if defends(cur, a, r))
        if nxt == cur:
            return cur
        cur = cur | nxt


def main() -> None:
    args, r = [0], set()
    chi = euler(args, r)
    p = len(preferred(args, r))
    g = len(grounded(args, r))
    print(f"chi(K(AF))              = {chi}")
    print(f"#preferred extensions   = {p}")
    print(f"|grounded extension|    = {g}")
    print(f"conjecture RHS (p - g)  = {p - g}")
    print(f"identity holds?         = {chi == p - g}")
    assert chi == 1 and p == 1 and g == 1 and chi != p - g
    print("REFUTED: 1 != 0.")


if __name__ == "__main__":
    main()

"""
The corrected topology-semantics correspondence for symmetric frameworks.

For symmetric, irreflexive frameworks, "conflict-free" coincides with
"independent set in the conflict graph", admissibility coincides with
conflict-freeness, and the preferred extensions are exactly the facets (maximal
faces) of the conflict-free complex K(AF) -- the maximal independent sets. For
the complete conflict graph on n vertices, chi(K(AF)) = n = #(preferred).
"""
from __future__ import annotations
from itertools import combinations, chain
from typing import FrozenSet, List, Set, Tuple

Ext = FrozenSet[int]
Rel = Set[Tuple[int, int]]


def powerset(xs: List[int]) -> List[Ext]:
    return [frozenset(c) for c in chain.from_iterable(
        combinations(xs, k) for k in range(len(xs) + 1))]


def conflict_free(s: Ext, r: Rel) -> bool:
    return not any((a, b) in r for a in s for b in s)


def faces(args: List[int], r: Rel) -> List[Ext]:
    return [s for s in powerset(args) if conflict_free(s, r)]


def facets(args: List[int], r: Rel) -> Set[Ext]:
    fs = faces(args, r)
    return {f for f in fs if not any(f < g for g in fs)}


def maximal_independent_sets(args: List[int], r: Rel) -> Set[Ext]:
    # symmetric case: preferred extensions = maximal independent sets
    return facets(args, r)


def euler(args: List[int], r: Rel) -> int:
    return sum((-1) ** (len(s) - 1) for s in faces(args, r) if len(s) > 0)


def symmetrize(edges: Set[Tuple[int, int]]) -> Rel:
    r: Rel = set()
    for a, b in edges:
        r.add((a, b)); r.add((b, a))
    return r


def main() -> None:
    # complete conflict graph on n vertices: chi = n = #preferred
    for n in range(2, 6):
        args = list(range(n))
        r = {(a, b) for a in args for b in args if a != b}
        print(f"K_{n}: chi = {euler(args, r)}, "
              f"#preferred = {len(maximal_independent_sets(args, r))}")
    # path graph 0-1-2-3
    args = [0, 1, 2, 3]
    r = symmetrize({(0, 1), (1, 2), (2, 3)})
    print("Path 0-1-2-3 preferred/facets:",
          sorted(sorted(s) for s in facets(args, r)))


if __name__ == "__main__":
    main()

