function PREFERRED(A, R):
    ADM <- [ S subset of A : S conflict-free and S defends every a in S ]
    return [ S in ADM : there is no T in ADM with S strictly contained in T ]

function EULER(A, R):
    chi <- 0
    for each nonempty s subset of A:
        if s is conflict-free (no a,b in s with (a,b) in R):
            chi <- chi + (-1)^(|s| - 1)
    return chi
